// An invented HTTP client, declared the way a `create({ prefixUrl })` client
// is: every call takes a path and an options bag, the body sits under the
// bag's `json` key, and the client itself is callable.

export interface Options {
  prefixUrl?: string;
  method?: string;
  json?: Record<string, unknown> | unknown[];
  headers?: Record<string, string>;
  searchParams?: Record<string, string>;
  retry?: number;
}

export interface ResponsePromise<T = unknown> extends Promise<T> {
  json<J = T>(): Promise<J>;
}

export interface PrefixClient {
  (url: string, options?: Options): ResponsePromise;
  get(url: string, options?: Options): ResponsePromise;
  post(url: string, options?: Options): ResponsePromise;
  create(defaults?: Options): PrefixClient;
}

declare const client: PrefixClient;
export default client;
